import { Component, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { LicnaKarta } from "../../models/LicnaKarta";
import { ZahteviService } from "../../services/zahtevi.service";
import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

declare var bootstrap: any;

@Component({
  selector: 'app-licna',
  templateUrl: './licna.component.html',
  styleUrls: ['./licna.component.css']
})
export class LicnaComponent implements OnInit, AfterViewInit {
  @ViewChild('zahtevModal', { static: false }) zahtevModalRef!: ElementRef;

  zahtevi: LicnaKarta[] = [];
  token: string = '';
  rola: string = '';

  noviZahtev = {
    jmbg: '',
    datumRodjenja: '',
    pol: 'M',
    grad: ''
  };

  modalInstance: any;
  today: string = '';

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'error';

  constructor(private zahteviService: ZahteviService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajZahteve();

    const danas = new Date();
    danas.setDate(danas.getDate() - 1);
    this.today = danas.toISOString().split('T')[0];
  }

  ngAfterViewInit(): void {
    // Proverimo da li element postoji u DOM-u
    if (this.zahtevModalRef && this.zahtevModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.zahtevModalRef.nativeElement);
    }
  }

  openZahtevModal(): void {
    if (this.modalInstance) {
      this.modalInstance.show();
    } else {
      console.error('Modal nije inicijalizovan!');
    }
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    this.zahteviService.podnesiZahtev(this.token, this.noviZahtev).subscribe({
      next: (res) => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm({ pol: 'M' });
        this.ucitajZahteve();
        this.alertType = 'success';
        this.alertMessage = res;
        this.showAlert = true;
      },
      error: (err) => {
        this.alertType = 'error';
        this.alertMessage = err.error || 'Došlo je do greške pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });
  }

  ucitajZahteve(): void {
    this.zahteviService.getSviZahtevi(this.token).subscribe({
      next: (data) => this.zahtevi = data,
      error: (err) => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    // Vraća true ako postoji zahtev u statusu CEKANJE ili DOZVOLJEN
    return this.zahtevi.some(zahtev => zahtev.status === 'CEKANJE' || zahtev.status === 'DOZVOLJEN');
  }


  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }
  prihvatiZahtev(id: number) {
    this.zahteviService.prihvatiZahtev(this.token, id).subscribe({
      next: (res: any) => {
        this.ucitajZahteve();

        // Ako server vrati objekat sa poljem message, uzmi samo poruku
        this.alertMessage = res?.message || 'Zahtev je odobren!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri prihvatanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.zahteviService.odbijZahtev(this.token, id).subscribe({
      next: (res: any) => {
        this.ucitajZahteve();
        this.alertMessage = res?.message || 'Zahtev je odbijen!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri odbijanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }
  get mozeProduziti(): boolean {
    // Vraća true ako postoji zahtev sa statusom DOZVOLJEN
    return this.zahtevi.some(zahtev => zahtev.status === 'DOZVOLJEN');
  }
  produziLicnuKartu() {
    this.zahteviService.produziLicnu(this.token).subscribe({
      next: (res: string) => {
        this.alertType = 'success';
        this.alertMessage = res || 'Lična karta je produžena!';
        this.showAlert = true;
        this.ucitajZahteve(); // refresujemo tabelu
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error || 'Došlo je do greške pri produženju.';
        this.showAlert = true;
      }
    });
  }
}
<app-custom-alert
  *ngIf="showAlert"
  [message]="alertMessage"
  [type]="alertType"
  (closed)="closeAlert()">
</app-custom-alert>

<div class="container mt-5">

  <!-- Dugme za podnošenje zahteva (sakriveno za EMPLOYER) -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!imaAktivanZahtev && !isEmployer">
    <button class="btn btn-primary me-3" (click)="openZahtevModal()">Zahtev za vađenje lične</button>
  </div>
  <div class="d-flex justify-content-center mb-4" *ngIf="!isEmployer && mozeProduziti">
    <button class="btn btn-warning" (click)="produziLicnuKartu()">Produži ličnu kartu</button>
  </div>

  <!-- Tabela: Aktivni zahtevi (sakriveno za EMPLOYER) -->
  <h3 class="mb-3 text-center" *ngIf="!isEmployer">Lična</h3>
  <div class="table-responsive mb-5" *ngIf="!isEmployer">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th><th>Ime</th><th>Prezime</th><th>JMBG</th>
        <th>Datum izdavanja</th><th>Važi do</th><th>Grad</th><th>Država</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let zahtev of zahtevi; let i = index">
        <tr *ngIf="zahtev.status === 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ zahtev.ime }}</td>
          <td>{{ zahtev.prezime }}</td>
          <td>{{ zahtev.jmbg }}</td>
          <td>{{ zahtev.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
          <td>{{ zahtev.datumVazenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ zahtev.grad }}</td>
          <td>{{ zahtev.drzava }}</td>
        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>

  <h3 class="mb-3 text-center">Zahtevi za ličnu</h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>JMBG</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Status</th>
        <th>Grad</th>
        <th>Država</th>
        <th *ngIf="isEmployer">Akcija</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let zahtev of zahtevi; let i = index">
        <!-- Prikaz za employer: svi zahtevi; za obican korisnik: samo oni koji nisu DOZVOLJEN -->
        <tr *ngIf="isEmployer || zahtev.status !== 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ zahtev.ime }}</td>
          <td>{{ zahtev.prezime }}</td>
          <td>{{ zahtev.jmbg }}</td>
          <td>{{ zahtev.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
          <td>{{ zahtev.datumVazenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ zahtev.status }}</td>
          <td>{{ zahtev.grad }}</td>
          <td>{{ zahtev.drzava }}</td>
          <!-- Dugmad samo za employer i ako status nije ODBIJEN -->
          <td *ngIf="isEmployer">
            <ng-container *ngIf="zahtev.status !== 'ODBIJEN' && zahtev.status !== 'DOZVOLJEN'">
              <button class="btn btn-success btn-sm me-2" (click)="prihvatiZahtev(zahtev.id)">Prihvati</button>
              <button class="btn btn-danger btn-sm" (click)="odbijZahtev(zahtev.id)">Odbij</button>
            </ng-container>
          </td>

        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>




</div>

<!-- Modal za podnošenje zahteva -->
<div class="modal fade" id="zahtevModal" #zahtevModal tabindex="-1" aria-labelledby="zahtevModalLabel" aria-hidden="true">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title" id="zahtevModalLabel">Podnesi zahtev za ličnu kartu</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
      </div>
      <div class="modal-body">
        <form #zahtevForm="ngForm" (ngSubmit)="podnesiZahtev(zahtevForm)">
          <div class="mb-3">
            <label for="jmbg" class="form-label">JMBG</label>
            <input type="text" class="form-control" id="jmbg" name="jmbg"
                   [(ngModel)]="noviZahtev.jmbg"
                   required minlength="13" maxlength="13"
                   #jmbgModel="ngModel">
            <div class="text-danger" *ngIf="jmbgModel.invalid && jmbgModel.touched">
              JMBG je obavezan i mora imati 13 cifara.
            </div>
          </div>

          <div class="mb-3">
            <label for="datumRodjenja" class="form-label">Datum rođenja</label>
            <input type="date" class="form-control" id="datumRodjenja" name="datumRodjenja"
                   [(ngModel)]="noviZahtev.datumRodjenja"
                   required #datumModel="ngModel"
                   max="{{ today }}">
            <div class="text-danger" *ngIf="datumModel.invalid && datumModel.touched">
              Datum rođenja je obavezan i mora biti u prošlosti.
            </div>
          </div>

          <div class="mb-3">
            <label for="pol" class="form-label">Pol</label>
            <select class="form-select" id="pol" name="pol"
                    [(ngModel)]="noviZahtev.pol"
                    required #polModel="ngModel">
              <option value="">Izaberite pol</option>
              <option value="M">Muški</option>
              <option value="Z">Ženski</option>
            </select>
            <div class="text-danger" *ngIf="polModel.invalid && polModel.touched">
              Pol je obavezan.
            </div>
          </div>

          <div class="mb-3">
            <label for="grad" class="form-label">Grad</label>
            <input type="text" class="form-control" id="grad" name="grad"
                   [(ngModel)]="noviZahtev.grad"
                   required #gradModel="ngModel">
            <div class="text-danger" *ngIf="gradModel.invalid && gradModel.touched">
              Grad je obavezan.
            </div>
          </div>

          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
            <button type="submit" class="btn btn-primary" [disabled]="zahtevForm.invalid">Podnesi zahtev</button>
          </div>
        </form>
      </div>
    </div>
  </div>
</div>
